param([string]$RemoteHost='h200-codex',[string]$RemoteRoot='/home/hera/pid_reliability_benchmark/outputs/final_replication',[string]$LocalRoot='outputs/final_replication')
$ErrorActionPreference='Stop'; $files=@('internvl35_a_p0_768.jsonl','internvl35_a_p0_3072.jsonl','internvl35_b_p0_768.jsonl','internvl35_b_p0_3072.jsonl'); $ssh=Join-Path $env:WINDIR 'System32/OpenSSH/ssh.exe'; $localDir=Join-Path (Get-Location) $LocalRoot; [IO.Directory]::CreateDirectory($localDir)|Out-Null
foreach($file in $files){$remotePath="$RemoteRoot/$file";$si=New-Object Diagnostics.ProcessStartInfo;$si.FileName=$ssh;$si.Arguments="-o BatchMode=yes $RemoteHost `"base64 -w0 $remotePath`"";$si.UseShellExecute=$false;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$p=New-Object Diagnostics.Process;$p.StartInfo=$si;[void]$p.Start();$enc=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode -ne 0){throw "pull failed $file $err"};$bytes=[Convert]::FromBase64String(($enc -replace '\s',''));[IO.File]::WriteAllBytes((Join-Path $localDir $file),$bytes);Write-Output("pulled {0} bytes={1}" -f $file,$bytes.Length)}
